// UI Events codes that Chromium knows but that have no evdev code (never sent as sc):
// Abort, FnLock, Hyper, NumpadBackspace, NumpadClear, NumpadClearEntry, NumpadMemoryAdd, NumpadMemoryClear, NumpadMemoryRecall, NumpadMemoryStore, NumpadMemorySubtract, Props, Resume, Super, Suspend, Turbo

// Portable pynput Key names (pynput/keyboard/_base.py, present on X11 and Windows).
const NAMED_BY_CODE = Object.freeze({
  Escape: "esc", Tab: "tab", Backspace: "backspace", Enter: "enter", NumpadEnter: "enter",
  Insert: "insert", Delete: "delete", Pause: "pause", PrintScreen: "print_screen",
  Home: "home", End: "end", PageUp: "page_up", PageDown: "page_down",
  ArrowLeft: "left", ArrowUp: "up", ArrowRight: "right", ArrowDown: "down",
  ShiftLeft: "shift", ShiftRight: "shift_r", ControlLeft: "ctrl", ControlRight: "ctrl_r",
  AltLeft: "alt", /* AltRight: decided by key (AltGraph -> alt_gr, else alt_r) */
  MetaLeft: "cmd", MetaRight: "cmd_r", OSLeft: "cmd", OSRight: "cmd_r",
  CapsLock: "caps_lock", NumLock: "num_lock", ScrollLock: "scroll_lock",
  ContextMenu: "menu", Space: "space",
  AudioVolumeMute: "media_volume_mute", AudioVolumeDown: "media_volume_down",
  AudioVolumeUp: "media_volume_up", VolumeMute: "media_volume_mute",
  VolumeDown: "media_volume_down", VolumeUp: "media_volume_up",
  MediaPlayPause: "media_play_pause", MediaTrackNext: "media_next",
  MediaTrackPrevious: "media_previous",
});

// Same, keyed by KeyboardEvent.key (used when code is "" / "Unidentified", e.g. some
// virtual keyboards and synthetic events).
const NAMED_BY_KEY = Object.freeze({
  Escape: "esc", Esc: "esc", Tab: "tab", Backspace: "backspace", Enter: "enter",
  Insert: "insert", Delete: "delete", Del: "delete", Pause: "pause", PrintScreen: "print_screen",
  Home: "home", End: "end", PageUp: "page_up", PageDown: "page_down",
  ArrowLeft: "left", ArrowUp: "up", ArrowRight: "right", ArrowDown: "down",
  Left: "left", Up: "up", Right: "right", Down: "down",
  Shift: "shift", Control: "ctrl", Alt: "alt", AltGraph: "alt_gr", Meta: "cmd", OS: "cmd",
  CapsLock: "caps_lock", NumLock: "num_lock", ScrollLock: "scroll_lock", Scroll: "scroll_lock",
  ContextMenu: "menu", Apps: "menu", " ": "space", Spacebar: "space",
  AudioVolumeMute: "media_volume_mute", AudioVolumeDown: "media_volume_down",
  AudioVolumeUp: "media_volume_up", MediaPlayPause: "media_play_pause",
  MediaTrackNext: "media_next", MediaTrackPrevious: "media_previous",
});

/** evdev code of a KeyboardEvent, or 0 if unknown (virtual keyboards report code ""). */
export function evdevCode(e) {
  return CODE_TO_EVDEV[e.code] || 0;
}

/**
 * pynput fallback name for the `k` field (mirrors remotedesk/gui/qtkeys.py key_name):
 * a pynput Key name, a lowercase letter, or a single printable character; null if none.
 */
export function keyName(e) {
  const code = e.code || "";
  if (code === "AltRight") return e.key === "AltGraph" ? "alt_gr" : "alt_r";
  let name = NAMED_BY_CODE[code];
  if (name) return name;
  const m = /^F([1-9]|1[0-9]|20)$/.exec(code) || /^F([1-9]|1[0-9]|20)$/.exec(e.key || "");
  if (m) return "f" + m[1];
  name = NAMED_BY_KEY[e.key];
  if (name) return name;
  if (/^Key[A-Z]$/.test(code)) return code.slice(3).toLowerCase();   // like Qt Key_A..Z
  if (/^Digit[0-9]$/.test(code) && /^[0-9]$/.test(e.key)) return e.key;
  const key = e.key || "";
  // One code point, printable (not "Dead", "Unidentified", "Process", ...).
  if ([...key].length === 1 && !/[\p{Cc}\p{Cf}]/u.test(key)) {
    return /^[A-Z]$/.test(key) ? key.toLowerCase() : key;
  }
  return null;
}

/** Protocol message for a key event, or null if nothing identifies the key. */
export function keyMessage(e, down) {
  const sc = evdevCode(e);
  const k = keyName(e);
  if (!sc && !k) return null;
  return { t: "key", down, sc, k };
}

export const EVDEV = Object.freeze({
  LEFTCTRL: 29, RIGHTALT: 100, LEFTMETA: 125, RIGHTMETA: 126, ESC: 1, PAUSE: 119,
});

function detectPlatform() {
  if (typeof navigator === "undefined") return "";
  return (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || "";
}

/**
 * Keyboard state tracker (desktop RemoteView semantics + browser quirks, cf. noVNC
 * core/input/keyboard.js):
 *  - keyup sends exactly what keydown sent; auto-repeat re-sends the stored down;
 *  - Windows AltGr: Windows injects a fake ControlLeft right before AltRight. The
 *    ControlLeft down is held back up to 100 ms; if AltRight follows within 50 ms the
 *    fake Ctrl is dropped (the remote never sees it), otherwise it is sent first;
 *  - Windows: releasing one Shift while the other is held gives no keyup for the
 *    other one -> release both;
 *  - macOS/iOS: no keyup for keys released while Cmd is held -> such keys are sent
 *    as an immediate press+release; CapsLock only reports state changes -> tap;
 *  - keys without `code` (virtual keyboards) -> immediate press+release;
 *  - IME composition (isComposing / keyCode 229) is ignored: use beforeinput instead;
 *  - releaseAll() for blur / visibilitychange / pagehide / disconnect;
 *  - option cmdAsCtrl: Cmd is sent as Ctrl (Mac viewer controlling Windows/Linux).
 * keydown()/keyup() return true when the event was consumed (call preventDefault()).
 */
export class KeyTracker {
  constructor(send, { platform = detectPlatform(), cmdAsCtrl = false } = {}) {
    this.send = send;
    this.cmdAsCtrl = cmdAsCtrl;               // Mac viewer -> Win/Linux host: Cmd+C = Ctrl+C
    this.mac = /mac|iphone|ipad|ipod/i.test(platform);
    this.win = /^win/i.test(platform);
    this.pressed = new Map();   // id -> {sc, k}
    this.armed = null;          // pending ControlLeft: {ts, msg, timer}
  }

  static id(e) { return e.code || ("key:" + e.key); }

  _message(e) {
    if (this.cmdAsCtrl && (e.code === "MetaLeft" || e.code === "OSLeft")) return { t: "key", down: true, sc: 29, k: "ctrl" };
    if (this.cmdAsCtrl && (e.code === "MetaRight" || e.code === "OSRight")) return { t: "key", down: true, sc: 97, k: "ctrl_r" };
    return keyMessage(e, true);
  }

  _tap(msg) {
    this.send({ t: "key", down: true, sc: msg.sc, k: msg.k });
    this.send({ t: "key", down: false, sc: msg.sc, k: msg.k });
  }

  _press(id, msg) {
    this.pressed.set(id, { sc: msg.sc, k: msg.k });
    this.send({ t: "key", down: true, sc: msg.sc, k: msg.k });
  }

  _release(id) {
    const o = this.pressed.get(id);
    if (!o) return;
    this.pressed.delete(id);
    this.send({ t: "key", down: false, sc: o.sc, k: o.k });
  }

  _disarm() {
    const a = this.armed;
    if (a) { clearTimeout(a.timer); this.armed = null; }
    return a;
  }

  /** Send a held-back ControlLeft (it was a real Ctrl, not AltGr). */
  flushPending() {
    const a = this._disarm();
    if (a) this._press("ControlLeft", a.msg);
  }

  keydown(e) {
    if (e.isComposing || e.keyCode === 229) return false;
    const id = KeyTracker.id(e);
    if (this.armed) {
      const a = this._disarm();
      if (!(e.code === "AltRight" && e.timeStamp - a.ts < 50)) this._press("ControlLeft", a.msg);
    }
    const prev = this.pressed.get(id);
    if (prev) {                                   // auto-repeat
      this.send({ t: "key", down: true, sc: prev.sc, k: prev.k });
      return true;
    }
    if (e.repeat) return true;                    // repeat of a key pressed before focus
    const msg = this._message(e);
    if (!msg) return false;
    if (!e.code) { this._tap(msg); return true; }
    if (this.mac && e.metaKey && !/^(Meta|OS)/.test(e.code)) { this._tap(msg); return true; }
    if (this.mac && e.code === "CapsLock") { this._tap(msg); return true; }
    if (this.win && e.code === "ControlLeft") {
      this.armed = { ts: e.timeStamp, msg, timer: setTimeout(() => this.flushPending(), 100) };
      return true;
    }
    this._press(id, msg);
    return true;
  }

  keyup(e) {
    this.flushPending();
    if (this.mac && e.code === "CapsLock") {
      const msg = this._message(e);
      if (msg) this._tap(msg);
      return true;
    }
    this._release(KeyTracker.id(e));
    if (this.win && (e.code === "ShiftLeft" || e.code === "ShiftRight")) {
      this._release("ShiftLeft");
      this._release("ShiftRight");
    }
    return true;
  }

  releaseAll() {
    this._disarm();
    for (const id of [...this.pressed.keys()]) this._release(id);
  }
}

/** True for the shortcuts that must reach the browser so a 'paste' event fires. */
export function isPasteShortcut(e) {
  return !!(((e.ctrlKey || e.metaKey) && !e.altKey && e.code === "KeyV") ||
            (e.shiftKey && e.code === "Insert"));
}
